def check(n, a, b):
    # We want to see if there exists any (x, y) != (0,0)
    # such that (ax + by) % n == 0 AND |x| + |y| < n
    for x in range(-n, n + 1):
        for y in range(-n, n + 1):
            if x == 0 and y == 0:
                continue
            if (a * x + b * y) % n == 0:
                if abs(x) + abs(y) < n:
                    return False
    return True

n = 36
found = False
for a in range(1, n):
    for b in range(1, n):
        if check(n, a, b):
            print(f"Found a={a}, b={b}")
            found = True
            break
    if found:
        break

if not found:
    print("No such (a, b) found for n=36.")

def solve_for_k_m(k, m):
    # Coloring f(x,y) = (x+y) % k.
    # Find the largest component of cells (x,y) such that (x+y) % k < m.
    # We use a grid of size (2k+2) x (2k+2).
    grid_size = 2 * k + 2
    allowed = [[False] * grid_size for _ in range(grid_size)]
    for x in range(grid_size):
        for y in range(grid_size):
            if (x + y) % k < m:
                allowed[x][y] = True

    visited = [[False] * grid_size for _ in range(grid_size)]
    max_area = 0
    for x in range(grid_size):
        for y in range(grid_size):
            if allowed[x][y] and not visited[x][y]:
                area = 0
                q = [(x, y)]
                visited[x][y] = True
                while q:
                    cx, cy = q.pop(0)
                    area += 1
                    for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nx, ny = cx + dx, cy + dy
                        if 0 <= nx < grid_size and 0 <= ny < grid_size:
                            if allowed[nx][ny] and not visited[nx][ny]:
                                visited[nx][ny] = True
                                q.append((nx, ny))
                max_area = max(max_area, area)
    return max_area

for k in [2, 3, 4, 5, 6]:
    print(f"k={k}, m={k-1}, max_area={solve_for_k_m(k, k-1)}")
